(7651880, 1244963, 53200, '<td valign="top">Huge Congratulations Deb!!!!  Fabulous shot!!!</td>', 'Huge Congratulations Deb!!!!  Fabulous shot!!!', '2020-01-29 08:49:33.000000', NULL, 0),
(7651882, 1244679, 100831, '<td valign="top">The scale is incredible. Youre so lucky to get to see that. Beautiful and it was my pick to win.</td>', 'The scale is incredible. Youre so lucky to get to see that. Beautiful and it was my pick to win.', '2020-01-29 08:58:30.000000', NULL, 0),
(7651888, 1244963, 38032, '<td valign="top">COngrats. Gave this one an 8.<br/>What puts this over the top for me is that you have brought us there. There''s an emotion and mood here that is captured wonderfully and I can imagine the warmth inside this place along with the blustery conditions of the environment. It''s one thing to find a place like this but it doesn''t guarantee a successful photo - Processed and composed very well on an image that could have been flat or overcooked. You nailed this one.</td>', 'COngrats. Gave this one an 8.What puts this over the top for me is that you have brought us there. There''s an emotion and mood here that is captured wonderfully and I can imagine the warmth inside this place along with the blustery conditions of the environment. It''s one thing to find a place like this but it doesn''t guarantee a successful photo - Processed and composed very well on an image that could have been flat or overcooked. You nailed this one.', '2020-01-29 10:24:17.000000', NULL, 0),
(7651934, 1244963, 112739, '<td valign="top">Well deserved blue! Good for you for being persistent. And thanks to your husband for turning around! I agree, the processing is just right. There would have been a real urge to take this too far with detail. Its a real image. Love the lights in the windows too, brings real sense of life to the image.</td>', 'Well deserved blue! Good for you for being persistent. And thanks to your husband for turning around! I agree, the processing is just right. There would have been a real urge to take this too far with detail. Its a real image. Love the lights in the windows too, brings real sense of life to the image.', '2020-01-29 12:00:49.000000', NULL, 0),
(7651940, 1244831, 112739, '<td valign="top">Beautiful sky, water, and overall just a great mood. A little saturated here and there, but no big deal. I think the dark hallows around the buildings caught my eye too much. Congrats on the Red with a fantastic image.</td>', 'Beautiful sky, water, and overall just a great mood. A little saturated here and there, but no big deal. I think the dark hallows around the buildings caught my eye too much. Congrats on the Red with a fantastic image.', '2020-01-29 12:05:32.000000', NULL, 0),
